BOOL ReadScopeList(wStream* s, SCOPE_LIST* scopeList)
{
    UINT32 scopeCount;

    if (Stream_GetRemainingLength(s) < 4)
        return FALSE;

    Stream_Read_UINT32(s, scopeCount);

    if (Stream_GetRemainingLength(s) < scopeCount * sizeof(LICENSE_BLOB))
        return FALSE;

    scopeList->scopeCount = scopeCount;
    scopeList->scopes = (LICENSE_BLOB*)malloc(scopeCount * sizeof(LICENSE_BLOB));

    if (!scopeList->scopes)
        return FALSE;

    for (UINT32 i = 0; i < scopeCount; i++)
    {
        LICENSE_BLOB* scope = &scopeList->scopes[i];

        if (Stream_GetRemainingLength(s) < sizeof(LICENSE_BLOB))
            return FALSE;

        Stream_Read(s, scope, sizeof(LICENSE_BLOB));
    }

    return TRUE;
}
